parameters.jsCode:
const input = $json.body;

const requiredFields = [
  'project_code',
  'change_title',
  'change_description',
  'requested_by',
  'priority'
];

const missingFields = requiredFields.filter(
  field => !input[field] || String(input[field]).trim() === ''
);

if (missingFields.length > 0) {
  throw new Error(`Missing required fields: ${missingFields.join(', ')}`);
}

const allowedPriorities = ['Low', 'Medium', 'High', 'Critical'];

if (!allowedPriorities.includes(input.priority)) {
  throw new Error(
    `Invalid priority '${input.priority}'. Allowed values: ${allowedPriorities.join(', ')}`
  );
}

if (
  input.requested_completion_date &&
  !/^\d{4}-\d{2}-\d{2}$/.test(input.requested_completion_date)
) {
  throw new Error(
    'requested_completion_date must use YYYY-MM-DD format'
  );
}

return [
  {
    json: {
      project_code: input.project_code.trim(),
      change_title: input.change_title.trim(),
      change_description: input.change_description.trim(),
      business_reason: input.business_reason?.trim() || null,
      requested_by: input.requested_by.trim(),
      priority: input.priority,
      requested_completion_date:
        input.requested_completion_date || null,
      validation_status: 'VALID'
    }
  }
];

const project = $json;

const request = $('Validate Change Request').first().json;

return [
  {
    json: {
      project_id: project.project_id,
      project_code: project.project_code,
      project_name: project.project_name,

      change_title: request.change_title,
      change_description: request.change_description,
      business_reason: request.business_reason,
      requested_by: request.requested_by,
      priority: request.priority,
      requested_completion_date: request.requested_completion_date,

      change_status: 'Submitted'
    }
  }
];

const input = $json;

const requestedDate = new Date(input.requested_completion_date);
const projectEndDate = new Date(input.project_planned_end_date);

const msPerDay = 1000 * 60 * 60 * 24;

const daysBeforeProjectEnd = Math.ceil(
  (projectEndDate - requestedDate) / msPerDay
);

const priorityWeights = {
  Low: 1,
  Medium: 2,
  High: 3,
  Critical: 4
};

const priorityWeight = priorityWeights[input.priority] || 0;

let schedulePressure;

if (daysBeforeProjectEnd < 0) {
  schedulePressure = 'Critical';
} else if (daysBeforeProjectEnd <= 30) {
  schedulePressure = 'High';
} else if (daysBeforeProjectEnd <= 90) {
  schedulePressure = 'Medium';
} else {
  schedulePressure = 'Low';
}

return [
  {
    json: {
      ...input,
      priority_weight: priorityWeight,
      days_before_project_end: daysBeforeProjectEnd,
      schedule_pressure: schedulePressure,
      deterministic_analysis_status: 'COMPLETED'
    }
  }
];

