parameters.jsCode:
const assessment = $json.output;

const context = $('Calculate Deterministic Impact').first().json;

const allowedRatings = ['Low', 'Medium', 'High', 'Critical'];

const allowedRecommendations = [
  'Proceed to Detailed Assessment',
  'Approve with Conditions',
  'Request More Information',
  'Defer',
  'Reject'
];

const ratingFields = [
  'schedule_rating',
  'cost_rating',
  'resource_rating',
  'technical_rating',
  'risk_rating',
  'overall_impact'
];

for (const field of ratingFields) {
  if (!allowedRatings.includes(assessment[field])) {
    throw new Error(`Invalid ${field}: ${assessment[field]}`);
  }
}

if (!allowedRecommendations.includes(assessment.recommendation)) {
  throw new Error(
    `Invalid recommendation: ${assessment.recommendation}`
  );
}

if (
  assessment.schedule_impact_days !== null &&
  !Number.isInteger(assessment.schedule_impact_days)
) {
  throw new Error(
    'schedule_impact_days must be an integer or null'
  );
}

if (
  assessment.cost_impact !== null &&
  typeof assessment.cost_impact !== 'number'
) {
  throw new Error(
    'cost_impact must be numeric or null'
  );
}

return [{
  json: {
    change_request_id: context.change_request_id,
    change_request_code: context.change_request_code,
    project_id: context.project_id,
    project_code: context.project_code,

    ...assessment,

    validation_status: 'VALID'
  }
}];

const created = $json;

const request = $('Validate Change Request').first().json;
const project = $('Get Project Context').first().json;

return [
  {
    json: {
      // Newly created database record
      change_request_id: created.change_request_id,
      change_request_code: created.change_request_code,

      // Project context
      project_id: project.project_id,
      project_code: project.project_code,
      project_name: project.project_name,
      project_status: project.project_status,
      project_manager: project.project_manager,
      project_start_date: project.start_date,
      project_planned_end_date: project.planned_end_date,
      project_budget: Number(project.budget || 0),
      currency: project.currency,

      // Original validated request
      change_title: request.change_title,
      change_description: request.change_description,
      business_reason: request.business_reason,
      requested_by: request.requested_by,
      priority: request.priority,
      requested_completion_date: request.requested_completion_date,

      change_status: created.change_status
    }
  }
];
